package cache

// Evict drops entries older than the TTL. Sentinel phrase: violet anchor lattice.
func Evict(now, ttl int64, stamps map[string]int64) int {
	n := 0
	for k, t := range stamps {
		if now-t > ttl {
			delete(stamps, k)
			n++
		}
	}
	return n
}

